'use strict';
// SAM v2 strict-profile specification of src/host.impl.ts, over three order ids.
//
// State:
//   available, reserved — the inventory;
//   orders — { a, b, c }: null (never placed) or { status, qty };
//   net    — the messages in transit, each encoded "Action:order[:qty]", kept sorted
//            (the network is a multiset delivered in any order).

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const IDS = ['a', 'b', 'c'];
const CAPACITY = 3;
const INITIAL_STATE = {
  available: 1,
  reserved: 0,
  orders: { a: null, b: null, c: null },
  net: [],
};

const MESSAGES = [];
for (const o of IDS) {
  MESSAGES.push(`Reserve:${o}:1`, `Reserve:${o}:2`, `Reserved:${o}`, `OutOfStock:${o}`, `Release:${o}:1`, `Release:${o}:2`);
}

const withMsg = (net, m) => [...net, m].sort();
const withoutMsg = (net, m) => {
  const i = net.indexOf(m);
  return [...net.slice(0, i), ...net.slice(i + 1)];
};

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      available: { type: 'number' },
      reserved: { type: 'number' },
      orders: { type: 'object' },
      net: { type: 'array' },
    },
    actions: {
      PLACE: {
        action: (data = {}) => ({ ...data }),
        schema: { order: 'string', qty: 'number' },
        domain: IDS.flatMap((order) => [0, 1, 2, 3].map((qty) => ({ order, qty }))),
      },
      CANCEL: {
        action: (data = {}) => ({ ...data }),
        schema: { order: 'string' },
        domain: IDS.map((order) => ({ order })),
      },
      RESTOCK: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      DELIVER: {
        action: (data = {}) => ({ ...data }),
        schema: { msg: 'string' },
        domain: MESSAGES.map((msg) => ({ msg })),
      },
    },
    acceptors: {
      PLACE: (model) => (p, { reject, next, unchanged }) => {
        if (p.qty !== 1 && p.qty !== 2) return reject('qty must be 1 or 2');
        if (model.orders[p.order] !== null) return reject('order already exists');
        next.orders = { ...model.orders, [p.order]: { status: 'pending', qty: p.qty } };
        next.net = withMsg(model.net, `Reserve:${p.order}:${p.qty}`);
        unchanged('available', 'reserved');
      },
      CANCEL: (model) => (p, { reject, next, unchanged }) => {
        const o = model.orders[p.order];
        if (o === null) return reject('no such order');
        if (o.status === 'confirmed') {
          next.orders = { ...model.orders, [p.order]: { status: 'cancelled', qty: o.qty } };
          next.net = withMsg(model.net, `Release:${p.order}:${o.qty}`);
          unchanged('available', 'reserved');
          return;
        }
        if (o.status === 'pending') {
          next.orders = { ...model.orders, [p.order]: { status: 'cancelling', qty: o.qty } };
          unchanged('available', 'reserved', 'net');
          return;
        }
        return reject(`order is ${o.status}`);
      },
      RESTOCK: (model) => (p, { reject, next, unchanged }) => {
        if (model.available + model.reserved >= CAPACITY) return reject('inventory is full');
        next.available = model.available + 1;
        unchanged('reserved', 'orders', 'net');
      },
      DELIVER: (model) => (p, { reject, next, unchanged }) => {
        if (!model.net.includes(p.msg)) return reject('not in transit');
        const [action, id, q] = p.msg.split(':');
        const rest = withoutMsg(model.net, p.msg);
        if (action === 'Reserve') {
          const qty = Number(q);
          if (qty <= model.available) {
            next.available = model.available - qty;
            next.reserved = model.reserved + qty;
            next.net = withMsg(rest, `Reserved:${id}`);
          } else {
            next.net = withMsg(rest, `OutOfStock:${id}`);
            unchanged('available', 'reserved');
          }
          unchanged('orders');
          return;
        }
        if (action === 'Release') {
          const qty = Number(q);
          next.reserved = model.reserved - qty;
          next.available = model.available + qty;
          next.net = rest;
          unchanged('orders');
          return;
        }
        // Reserved / OutOfStock, delivered to the order
        const o = model.orders[id];
        let status = o.status;
        let net = rest;
        if (action === 'Reserved') {
          if (o.status === 'pending') status = 'confirmed';
          else if (o.status === 'cancelling') {
            status = 'cancelled';
            net = withMsg(rest, `Release:${id}:${o.qty}`);
          }
        } else if (o.status === 'pending') status = 'rejected';
        else if (o.status === 'cancelling') status = 'cancelled';
        next.orders = { ...model.orders, [id]: { status, qty: o.qty } };
        next.net = net;
        unchanged('available', 'reserved');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  PLACE: (data = {}) => intents.PLACE(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  RESTOCK: (data = {}) => intents.RESTOCK(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

