// still travelling, or released with the Release still travelling.
const owed = (s) => {
  let n = 0;
  for (const [id, o] of orders(s)) {
    if (o.status === 'confirmed') n += o.qty;
    n += count(s.net, `Reserved:${id}`) * o.qty;
    n += count(s.net, `Release:${id}:`) * o.qty;
  }
  return n;
};

