// Rules the brief requires, as invariants over the spec's state.

const orders = (s) => Object.entries(s.orders).filter(([, o]) => o !== null);
const count = (net, prefix) => net.filter((m) => m.startsWith(prefix)).length;
const qtyOf = (s, id) => s.orders[id].qty;

// Units the inventory holds on an order's behalf: confirmed, or reserved with the answer
// still travelling, or released with the Release still travelling.
const owed = (s) => {
  let n = 0;
  for (const [id, o] of orders(s)) {
    if (o.status === 'confirmed') n += o.qty;
    n += count(s.net, `Reserved:${id}`) * o.qty;
    n += count(s.net, `Release:${id}:`) * o.qty;
  }
  return n;
};

export const stateInvariants = [
  { name: 'stock-non-negative', pred: (s) => s.available >= 0 && s.reserved >= 0 },
  { name: 'capacity', pred: (s) => s.available + s.reserved <= 3 },
  { name: 'open-is-boolean', pred: (s) => typeof s.open === 'boolean' },
  { name: 'units-conserved', pred: (s) => s.reserved === owed(s) },
  {
    name: 'quiescent-reserved-equals-confirmed',
    pred: (s) =>
      s.net.length > 0 ||
      s.reserved === orders(s).reduce((n, [, o]) => n + (o.status === 'confirmed' ? o.qty : 0), 0),
  },
  { name: 'qty-is-1-or-2', pred: (s) => orders(s).every(([, o]) => o.qty === 1 || o.qty === 2) },
  {
    name: 'one-request-per-order',
    pred: (s) =>
      orders(s).every(([id]) => count(s.net, `Reserve:${id}:`) + count(s.net, `Reserved:${id}`) + count(s.net, `OutOfStock:${id}`) <= 1),
  },
  {
    name: 'awaiting-orders-have-a-request',
    pred: (s) =>
      orders(s).every(([id, o]) =>
        !(o.status === 'pending' || o.status === 'cancelling') ||
        count(s.net, `Reserve:${id}:`) + count(s.net, `Reserved:${id}`) + count(s.net, `OutOfStock:${id}`) === 1),
  },
  {
    name: 'release-matches-order',
    pred: (s) =>
      orders(s).every(([id, o]) =>
        s.net.filter((m) => m.startsWith(`Release:${id}:`)).every((m) => m === `Release:${id}:${o.qty}` && (o.status === 'cancelled' || o.status === 'expired'))),
  },
];

const statusOf = (s, id) => (s.orders[id] ? s.orders[id].status : null);

export const transitionInvariants = [
  {
    name: 'confirmed-only-from-pending-on-Reserved',
    pred: (pre, action, data, post) =>
      Object.keys(post.orders).every((id) =>
        statusOf(post, id) !== 'confirmed' || statusOf(pre, id) === 'confirmed' ||
        (action === 'DELIVER' && data.msg === `Reserved:${id}` && statusOf(pre, id) === 'pending')),
  },
  {
    name: 'final-statuses-are-final',
    pred: (pre, action, data, post) =>
      Object.keys(pre.orders).every((id) =>
        !['rejected', 'cancelled', 'expired'].includes(statusOf(pre, id)) || statusOf(post, id) === statusOf(pre, id)),
  },
  {
    name: 'cancel-or-expiry-of-confirmed-order-gives-back',
    pred: (pre, action, data, post) =>
      Object.keys(post.orders).every((id) =>
        !(statusOf(pre, id) === 'confirmed' && ['cancelled', 'expired'].includes(statusOf(post, id))) ||
        count(post.net, `Release:${id}:`) === count(pre.net, `Release:${id}:`) + 1),
  },
  {
    name: 'expired-only-from-confirmed-by-EXPIRE',
    pred: (pre, action, data, post) =>
      Object.keys(post.orders).every((id) =>
        statusOf(post, id) !== 'expired' || statusOf(pre, id) === 'expired' ||
        (action === 'EXPIRE' && data.order === id && statusOf(pre, id) === 'confirmed')),
  },
  {
    name: 'closed-inventory-reserves-nothing',
    pred: (pre, action, data, post) => pre.open || !(post.reserved > pre.reserved),
  },
  {
    name: 'closed-inventory-answers-OutOfStock',
    pred: (pre, action, data, post) =>
      pre.open || action !== 'DELIVER' || !data.msg.startsWith('Reserve:') || !pre.net.includes(data.msg) ||
      count(post.net, `OutOfStock:${data.msg.split(':')[1]}`) === count(pre.net, `OutOfStock:${data.msg.split(':')[1]}`) + 1,
  },
  {
    name: 'closed-inventory-not-restocked',
    pred: (pre, action, data, post) => pre.open || action !== 'RESTOCK' || post.available === pre.available,
  },
  {
    name: 'closed-inventory-takes-Release',
    pred: (pre, action, data, post) =>
      pre.open || action !== 'DELIVER' || !data.msg.startsWith('Release:') || !pre.net.includes(data.msg) ||
      post.available > pre.available,
  },
  {
    name: 'qty-never-changes',
    pred: (pre, action, data, post) =>
      Object.keys(pre.orders).every((id) => pre.orders[id] === null || post.orders[id].qty === qtyOf(pre, id)),
  },
];

