import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import { loadSpec } from '../tools/polygraph/scripts/load-spec.mjs';

test('initial state', async () => {
  const h = await createHost();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.deepEqual(await h.inFlight(), []);
  assert.equal(await h.order('x'), null);
});

test('place, confirm, cancel', async () => {
  const h = await createHost();
  assert.deepEqual(await h.place('x', 1), { ok: true });
  assert.deepEqual(await h.order('x'), { status: 'pending', qty: 1 });
  const [m] = await h.inFlight();
  assert.deepEqual({ ...m, id: undefined }, { id: undefined, from: 'x', to: 'inventory', action: 'Reserve', data: { from: 'x', qty: 1 } });
  await h.deliver(m.id);
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1, open: true });
  const [r] = await h.inFlight();
  assert.equal(r.action, 'Reserved');
  assert.equal(r.to, 'x');
  await h.deliverAll();
  assert.equal((await h.order('x'))!.status, 'confirmed');
  assert.deepEqual(await h.cancel('x'), { ok: true });
  assert.equal((await h.order('x'))!.status, 'cancelled');
  const [rel] = await h.inFlight();
  assert.deepEqual([rel.action, rel.data], ['Release', { qty: 1 }]);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.equal((await h.cancel('x')).ok, false);
});

test('refusals', async () => {
  const h = await createHost();
  for (const q of [0, 3, 1.5, -1]) assert.equal((await h.place('x', q)).ok, false);
  assert.equal((await h.cancel('nope')).ok, false);
  assert.deepEqual(await h.inFlight(), []);
  await h.place('x', 2);
  assert.equal((await h.place('x', 1)).ok, false);
  await h.deliverAll();
  assert.equal((await h.order('x'))!.status, 'rejected');
  assert.equal((await h.cancel('x')).ok, false);
  assert.deepEqual(await h.restock(), { ok: true });
  assert.deepEqual(await h.restock(), { ok: true });
  assert.equal((await h.restock()).ok, false);
  assert.deepEqual(await h.stock(), { available: 3, reserved: 0, open: true });
});

test('cancel while pending, answer Reserved gives units back', async () => {
  const h = await createHost();
  await h.place('x', 1);
  await h.cancel('x');
  assert.equal((await h.order('x'))!.status, 'cancelling');
  assert.equal((await h.cancel('x')).ok, false);
  await h.deliverAll();
  assert.equal((await h.order('x'))!.status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
});

test('cancel while pending, answer OutOfStock', async () => {
  const h = await createHost();
  await h.place('x', 2);
  await h.cancel('x');
  await h.deliverAll();
  assert.deepEqual(await h.order('x'), { status: 'cancelled', qty: 2 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
});

test('expire a confirmed order gives units back; expired accepts no command', async () => {
  const h = await createHost();
  assert.equal((await h.expire('x')).ok, false);
  await h.place('x', 1);
  assert.equal((await h.expire('x')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.expire('x'), { ok: true });
  assert.deepEqual(await h.order('x'), { status: 'expired', qty: 1 });
  const [rel] = await h.inFlight();
  assert.deepEqual([rel.from, rel.to, rel.action, rel.data], ['x', 'inventory', 'Release', { qty: 1 }]);
  assert.equal((await h.expire('x')).ok, false);
  assert.equal((await h.cancel('x')).ok, false);
  assert.equal((await h.place('x', 1)).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.equal((await h.order('x'))!.status, 'expired');
});

test('expire refused for cancelling, cancelled and rejected orders', async () => {
  const h = await createHost();
  await h.place('p', 1);
  await h.cancel('p');
  assert.equal((await h.expire('p')).ok, false);
  await h.place('r', 2);
  await h.deliverAll();
  assert.equal((await h.order('r'))!.status, 'rejected');
  assert.equal((await h.expire('r')).ok, false);
  assert.equal((await h.order('p'))!.status, 'cancelled');
  assert.equal((await h.expire('p')).ok, false);
});

test('closed inventory: OutOfStock to Reserve, no restock, Release taken', async () => {
  const h = await createHost();
  assert.equal((await h.open()).ok, false);
  await h.place('x', 1);
  await h.deliverAll();
  assert.deepEqual(await h.close(), { ok: true });
  assert.equal((await h.close()).ok, false);
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1, open: false });
  assert.equal((await h.restock()).ok, false);
  await h.cancel('x');
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
  await h.place('y', 1);
  await h.deliverAll();
  assert.equal((await h.order('y'))!.status, 'rejected');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
  assert.deepEqual(await h.open(), { ok: true });
  assert.deepEqual(await h.restock(), { ok: true });
  await h.place('z', 2);
  await h.deliverAll();
  assert.equal((await h.order('z'))!.status, 'confirmed');
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2, open: true });
});

test('a Reserve sent while open but delivered while closed is OutOfStock', async () => {
  const h = await createHost();
  await h.place('x', 1);
  await h.close();
  await h.deliverAll();
  assert.equal((await h.order('x'))!.status, 'rejected');
});

// Conformance: random walks drive the implementation and the polygraph spec in lockstep.
const IDS = ['a', 'b', 'c'];
const encode = (m: { action: string; to: string; from: string; data: Record<string, unknown> }) => {
  if (m.action === 'Reserve') return `Reserve:${m.from}:${m.data.qty}`;
  if (m.action === 'Release') return `Release:${m.from}:${m.data.qty}`;
  return `${m.action}:${m.to}`;
};
const observe = async (h: Awaited<ReturnType<typeof createHost>>) => {
  const s = await h.stock();
  const orders: Record<string, unknown> = {};
  for (const id of IDS) orders[id] = await h.order(id);
  const net = (await h.inFlight()).map(encode).sort();
  return { available: s.available, reserved: s.reserved, open: s.open, orders, net };
};

test('implementation conforms to spec/orders.cjs', async () => {
  const spec = loadSpec('spec/orders.cjs');
  let seed = 12345;
  const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };
  for (let walk = 0; walk < 300; walk++) {
    const h = await createHost();
    spec.init();
    for (let step = 0; step < 30; step++) {
      const k = rnd(7);
      if (k === 5) {
        await h.close();
        spec.actions.CLOSE({});
        assert.deepEqual(await observe(h), spec.getState(), `walk ${walk} step ${step}`);
        continue;
      }
      if (k === 6) {
        await h.open();
        spec.actions.OPEN({});
        assert.deepEqual(await observe(h), spec.getState(), `walk ${walk} step ${step}`);
        continue;
      }
      if (k === 0) {
        const order = IDS[rnd(3)], qty = rnd(4);
        const out = await h.place(order, qty);
        spec.actions.PLACE({ order, qty });
        void out;
      } else if (k === 1) {
        const order = IDS[rnd(3)];
        await h.cancel(order);
        spec.actions.CANCEL({ order });
      } else if (k === 2) {
        await h.restock();
        spec.actions.RESTOCK({});
      } else if (k === 3) {
        const order = IDS[rnd(3)];
        await h.expire(order);
        spec.actions.EXPIRE({ order });
      } else {
